function [ok] = modes_feasible(nr, nc, m)
%MODES_FEASIBLE  Can the fitted hardware fly a state? Fine pointing needs rotors or thrusters, the rotor Sun
%   acquisition rotors, the thruster detumble thrusters; the coil states need only the coils.
%   nr: int (passed a whole number)
%   nc: int (passed a whole number)
%   m: int (passed a whole number)
%   returns ok: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ok = false;
    if ((((m == 2) || (m == 3)) || (m == 4)) || (m == 10))
        ok = ((nr > 0) || (nc > 0));
    elseif (m == 8)
        ok = (nr > 0);
    elseif (m == 7)
        ok = (nc > 0);
    else
        ok = (m < 11);
    end
end
